def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr, cc in ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1))):
                # Diagonal markers around the 2x2 block: TL, TR, BL, BR.
                anchors = [(r - 1, c - 1), (r - 1, c + 2), (r + 2, c - 1), (r + 2, c + 2)]
                if not all(0 <= ar < h and 0 <= ac < w for ar, ac in anchors):
                    continue
                tl, tr, bl, br = [grid[ar][ac] for ar, ac in anchors]
                # Rotate the four marker colors around the block, then extend each
                # marker diagonally away from the block to the edge of the grid.
                colors = [bl, tl, br, tr]
                directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
                for (ar, ac), color, (dr, dc) in zip(anchors, colors, directions):
                    rr, cc = ar, ac
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
